    1. If values form diagonal bands (each value at positions with same i+j):
       output[i][j] = pattern[(i+j) mod N] where N = number of unique values
    2. If values form horizontal stripes (each row has constant non-zero value):
       output[i][j] = pattern[i mod N] where N = number of unique non-zero rows
    """
    rows = len(grid)
    cols = len(grid[0])

    # Find all non-zero positions
    nonzero = []
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != 0:
                nonzero.append((i, j, grid[i][j]))

    if not nonzero:
        # Empty input, return zero grid
        return [[0] * cols for _ in range(rows)]

    # Check if pattern is diagonal bands (each value at positions with same i+j)
    by_value = {}
    for i, j, v in nonzero:
        if v not in by_value:
            by_value[v] = set((i, j))
        else:
